CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, full_name VARCHAR(120) NOT NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE roles (name VARCHAR(20) PRIMARY KEY);
INSERT INTO roles(name) VALUES ('ADMIN'), ('CUSTOMER');
CREATE TABLE user_roles (user_id BIGINT NOT NULL, role VARCHAR(20) NOT NULL, PRIMARY KEY(user_id, role), CONSTRAINT fk_role_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT fk_user_roles_role FOREIGN KEY(role) REFERENCES roles(name));
CREATE TABLE accounts (id BIGINT PRIMARY KEY AUTO_INCREMENT, account_number VARCHAR(24) NOT NULL UNIQUE, owner_id BIGINT NOT NULL, balance DECIMAL(19,2) NOT NULL DEFAULT 0, status VARCHAR(16) NOT NULL, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), CONSTRAINT fk_account_owner FOREIGN KEY(owner_id) REFERENCES users(id), CONSTRAINT chk_account_balance_nonnegative CHECK (balance >= 0), INDEX idx_accounts_owner(owner_id));
CREATE TABLE transactions (id BIGINT PRIMARY KEY AUTO_INCREMENT, reference_id VARCHAR(36) NOT NULL, account_id BIGINT NOT NULL, type VARCHAR(20) NOT NULL, amount DECIMAL(19,2) NOT NULL, balance_after DECIMAL(19,2) NOT NULL, description VARCHAR(255), created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), CONSTRAINT fk_tx_account FOREIGN KEY(account_id) REFERENCES accounts(id), CONSTRAINT chk_transaction_amount_positive CHECK (amount > 0), INDEX idx_tx_account_created(account_id,created_at), INDEX idx_tx_reference(reference_id));
CREATE TABLE idempotency_records (id BIGINT PRIMARY KEY AUTO_INCREMENT, owner_id BIGINT NOT NULL, idempotency_key VARCHAR(100) NOT NULL, reference_id VARCHAR(36) NOT NULL, request_hash VARCHAR(64) NOT NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), CONSTRAINT fk_idem_owner FOREIGN KEY(owner_id) REFERENCES users(id), CONSTRAINT uk_idempotency_owner_key UNIQUE(owner_id,idempotency_key));
CREATE TABLE audit_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, actor_id BIGINT, action VARCHAR(80) NOT NULL, details VARCHAR(500), created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), INDEX idx_audit_created(created_at));
CREATE TABLE revoked_tokens (token_id VARCHAR(36) PRIMARY KEY, expires_at TIMESTAMP(6) NOT NULL, INDEX idx_revoked_expires(expires_at));
CREATE TABLE refresh_tokens (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMP(6) NOT NULL, revoked_at TIMESTAMP(6), created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), CONSTRAINT fk_refresh_user FOREIGN KEY(user_id) REFERENCES users(id), INDEX idx_refresh_expires(expires_at));
